import 'package:flutter_test/flutter_test.dart';
import 'package:bloc_test/bloc_test.dart';
import 'package:hw12_booksale/book_bloc.dart';
import 'package:hw12_booksale/book_repository.dart';
import 'package:mocktail/mocktail.dart';
import 'package:hw12_booksale/book.dart';

class MockBookRepository extends Mock implements BookRepository {}

final books = [
  Book(
    id: '1',
    title: 'Flutter for Beginners',
    category: 'Programming',
    coverUrl:
        'data:image/jpeg;base64,',
    price: 25.0,
    pages: 300,
    samplePages: [
      'https://images.unsplash.com/photo-1528459199957-0ff28496a7f6?w=900&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8NHx8Ym9vayUyMHBhZ2VzfGVufDB8fDB8fHww',
      'https://images.unsplash.com/photo-1528459135417-42dfc609ce87?q=80&w=3158&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D',
      'https://images.unsplash.com/photo-1528459199957-0ff28496a7f6?q=80&w=3143&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D',
    ],
  ),
];

void main() {
  late MockBookRepository mockBookRepository;
  late BookBloc bookBloc;

  setUp(() {
    mockBookRepository = MockBookRepository();
    bookBloc = BookBloc(mockBookRepository);
    final books = [
      Book(
        id: '1',
        title: 'Flutter for Beginners',
        category: 'Programming',
        coverUrl:
            'data:image/jpeg;base64,',
        price: 25.0,
        pages: 300,
        samplePages: [
          'https://images.unsplash.com/photo-1528459199957-0ff28496a7f6?w=900&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8NHx8Ym9vayUyMHBhZ2VzfGVufDB8fDB8fHww',
          'https://images.unsplash.com/photo-1528459135417-42dfc609ce87?q=80&w=3158&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D',
          'https://images.unsplash.com/photo-1528459199957-0ff28496a7f6?q=80&w=3143&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D',
        ],
      ),
    ];

    when(() => mockBookRepository.fetchBooks()).thenAnswer((_) async => books);
  });

  tearDown(() {
    bookBloc.close();
  });

  blocTest<BookBloc, BookState>(
    'emits [BookLoading, BookLoaded] when FetchBooks is added',
    build: () => bookBloc,
    act: (bloc) => bloc.add(FetchBooks()),
    expect: () => [isA<BookLoading>()],
  );

  blocTest<BookBloc, BookState>(
    'emits [BookLoading, BookLoaded with filtered books] when FilterBooksByCategory is added',
    build: () => bookBloc,
    act: (bloc) => bloc.add(FilterBooksByCategory('Programming')),
    expect: () => [isA<BookLoading>()],
  );
}
